import Constellation from './Constellation';
import './WorkHeroSky.css';

const PLACEMENTS = {
  aquila: { left: 55, top: 0, width: 43, height: 38 },
  pisces: { left: 50, top: 22, width: 32, height: 18 },
  delphinus: { left: 86, top: 28, width: 14, height: 14 },
};

export default function WorkHeroSky({ active }) {
  return (
    <div className="work-hero__sky" aria-hidden="true">
      <img
        src="/images/work/work-sky.svg"
        alt=""
        className="work-hero__sky-bg"
      />

      {Object.entries(PLACEMENTS).map(([variant, box]) => (
        <div
          key={variant}
          className={`work-hero__constellation-slot work-hero__constellation-slot--${variant}`}
          style={{
            left: `${box.left}%`,
            top: `${box.top}%`,
            width: `${box.width}%`,
            height: `${box.height}%`,
          }}
        >
          <Constellation variant={variant} active={active} />
        </div>
      ))}
    </div>
  );
}
